namespace {
std::int32_t lookup_name(const char* const* names, std::uint32_t n, const char* name) {
    if (!name) return 0;
    for (std::uint32_t i = 1; i <= n; ++i)
        if (std::strcmp(names[i], name) == 0) return static_cast<std::int32_t>(i);
    return 0;  // unknown
}
}

Mnemonic mnemonic_from_name(const char* name) {
    return static_cast<Mnemonic>(lookup_name(kMnemonicNames, kNumMnemonics, name));
}
VariantClass variant_class_from_name(const char* name) {
    return static_cast<VariantClass>(lookup_name(kVariantClassNames, kNumVariantClasses, name));
}
Pipe pipe_from_name(const char* name) {
    return static_cast<Pipe>(lookup_name(kPipeNames, kNumPipes, name));
}

